  "sim.network-noc.title": "نیٹ ورک NOC",
  "sim.network-noc.desc": "نیٹ ورک آپریشنز سینٹر انجینئر کے طور پر کام کریں — دباؤ کے تحت لائیو انفراسٹرکچر کے مسائل کی تشخیص اور حل کریں۔",
  "sim.mobile-repair.title": "موبائل ریپیئر ورکشاپ",
  "sim.mobile-repair.desc": "اسمارٹ فونز کی تشخیص اور درست کریں — اسکرین تبدیلیاں، بیٹری کے مسائل، اور مدر بورڈ فالٹس۔",
  "sim.laptop-repair.title": "لیپ ٹاپ ریپیئر ورکشاپ",
  "sim.laptop-repair.desc": "لیپ ٹاپس کی ٹربل شوٹنگ اور مرمت کریں: ہارڈویئر فالٹس، BIOS مسائل، اور کمپوننٹ تبدیلیاں۔",
  "sim.perfume-lab.title": "پرفیوم لیب",
  "sim.perfume-lab.desc": "ضروری تیل اور خوشبوئی مرکبات کو مکس کریں تاکہ منفرد خوشبوئیں بنیں اور کوالٹی بینچ مارکس پورے ہوں۔",
  "sim.detergent-lab.title": "ڈٹرجنٹ لیب",
  "sim.detergent-lab.desc": "صفائی کی مصنوعات تیار کریں — بجٹ کے اندر سرفیکٹینٹس، فلرز، اور پرفارمنس ٹیسٹس کا توازن رکھیں۔",
  "sim.skin-care-lab.title": "سکن کیئر لیب",
  "sim.skin-care-lab.desc": "کاسمیٹک فارمولیشنز تیار اور ٹیسٹ کریں، سیفٹی اسٹینڈرڈز اور افیکسیٹی اہداف پورے کرتے ہوئے۔",
  "sim.woodworking.title": "ورکنگ بڑھئی کی ورکشاپ",
  "sim.woodworking.desc": "حسبِ ضرورت بڑھئی کی دکان چلائیں: کاموں کی پلاننگ، میٹریلز مینج کرنا، اور فرنیچر وقت پر اور بجٹ کے اندر ڈیلیور کرنا۔",
  "sim.aluminum-glazing.title": "ایلومینیم & گلیزنگ",
  "sim.aluminum-glazing.desc": "کوٹیشن سے لے کر سائٹ کی تکمیل تک ایلومینیم فیبریکیشن اور گلاس انسٹالیشن کا کاروبار چلائیں۔",
  "sim.global-kitchen.title": "گلوبل کچن",
  "sim.global-kitchen.desc": "ریسٹورنٹ کچن کی قیادت کریں: مینو مینج کریں، اسٹاف، لاگت، اور سروس شفٹس کے دوران کسٹمر سیٹِسفکشن کو بہتر بنائیں۔",
  "sim.chocolate-factory.title": "چاکلیٹ فیکٹری",
  "sim.chocolate-factory.desc": "ایک کنفیکشنری فیکٹری چلائیں — کوکو کی سورسنگ، پروڈکشن شیڈولنگ، اور کوالٹی کنٹرول۔",
  "sim.solar-energy.title": "سولر انرجی پلانٹ",
  "sim.solar-energy.desc": "سولر انسٹالیشن ڈیزائن اور آپریٹ کریں — پینلز کا سائز، گرڈ ایکسپورٹ مینج کرنا، اور ROI ٹریک کرنا۔",
  "sim.hvac-systems.title": "HVAC سسٹمز",
  "sim.hvac-systems.desc": "کمرشل عمارتوں کے لیے ہیٹنگ، وینٹی لیشن، اور ائر کنڈیشننگ سسٹمز انسٹال اور مینٹین کریں۔",
  "sim.logistics-supply.title": "لا جِسٹکس & سپلائی چین",
  "sim.logistics-supply.desc": "گودام کی آپریشنز، فلیٹ روٹنگ، اور سپلائر ریلیشنز کو بہتر بنائیں تاکہ ڈیلیوری KPIs پورے ہوں۔",
  "sim.barber-salon.title": "باربر سیلون",
  "sim.barber-salon.desc": "باربر شاپ مینج کریں: اپائنٹمنٹس، اسٹاف شیڈولز، قیمتیں، اور کسٹمر ریٹینشن کی حکمتِ عملیاں۔",
  "sim.board-surgeon.title": "بورڈ سرجن",
  "sim.board-surgeon.desc": "سمولیٹڈ آپریٹنگ تھیٹر میں ہائی اسٹیکس سرجیکل فیصلے کریں — ٹائم مینجمنٹ اور مریض کی سیفٹی۔",
  "sim.english-journey.title": "انگلش جرنی",
  "sim.english-journey.desc": "سیکھنے والوں کو انگلش لینگویج کے منظم پروگرام کے ذریعے گائیڈ کریں، مختلف مہارت کی سطحوں کے مطابق۔",
  "sim.music-training.title": "میوزک ٹریننگ اسٹوڈیو",
  "sim.music-training.desc": "ایک میوزک اسکول چلائیں: لیسنز شیڈول کریں، آلات مینج کریں، اور طلبہ کی ریکائٹل تک پیش رفت کو ٹریک کریں۔",
  "sim.trade-tycoon.title": "ٹریڈ ٹائیکون",
  "sim.trade-tycoon.desc": "ایک ٹریڈنگ سلطنت بنائیں — کم میں خریدیں، زیادہ میں فروخت کریں، اور متعدد مارکیٹس میں انوینٹری اور کیش فلو مینج کریں۔",
  "sim.vehicle-diagnostics.title": "ویہییکل ڈیگناسٹکس اینڈ ریپئر سمولیٹر",
  "sim.vehicle-diagnostics.desc": "OBD-II فالٹ کوڈز کی تشخیص کریں، برقی فالٹس کی نشاندہی کریں، اور حقیقی دنیا کے آٹو ریپیئر ورک فلو کو مینج کریں۔",
  "sim.marine-vessel.title": "میرین ویزل ٹریکنگ & میری ٹائم لا جِسٹکس",
  "sim.marine-vessel.desc": "ایک عالمی بیڑے کی کمان سنبھالیں — جہازوں کو ٹریک کریں، بندرگاہوں کی بھیڑ، موسم کی ایمرجینسی، اور کینال میں تاخیر کو نیویگیٹ کریں۔",
