  "legal.market.prohibited.wildlife.title": "محفوظ جانور & جنگلی حیات",
  "legal.market.prohibited.wildlife.desc": "مخدوش نسلیں (endangered species)، ہاتھی دانت جیسے غیر قانونی جانوروں کی مصنوعات، محفوظ شدہ کھال، اور زندہ جانور۔",
