  "legal.market.prohibited.data.title": "ذاتی ڈیٹا & پرائیویسی",
  "legal.market.prohibited.data.desc": "ذاتی معلومات بیچنا، صارفین کی ڈیٹا بیسز (databases)، نجی رابطہ لسٹس، یا رضامندی کے بغیر جمع کیا گیا ڈیٹا۔",
  "legal.market.prohibited.hate.title": "نفرت اور امتیاز",
  "legal.market.prohibited.hate.desc": "ایسی مصنوعات، علامتیں، یا سامان جو کسی بھی گروہ کے خلاف نفرت، امتیاز، یا تشدد کو فروغ دیں۔",
