  "legal.market.allowed.home": "گھر کے سامان، فرنیچر، اور ڈیکور۔",
  "legal.market.allowed.health": "صحت اور تندرستی کی ایسی مصنوعات جن کے دعوے تصدیق شدہ اور سچے ہوں۔",
