  "legal.ip.timeline.decision.label": "فیصلہ جاری",
  "legal.ip.timeline.decision.desc": "اگر خلاف ورزی ثابت ہو جائے تو 5 کاروباری دنوں کے اندر مواد ہٹا دیا جاتا ہے یا نوٹس مسترد کر دیا جاتا ہے۔",
  "legal.ip.counterTitle": "جوابی نوٹس (ہٹانے پر اختلاف)",
  "legal.ip.counterIntro": "اگر آپ کا مواد ہٹا دیا گیا ہے اور آپ سمجھتے ہیں کہ ہٹانا غلطی پر مبنی تھا تو آپ یہ شامل کرتے ہوئے جوابی نوٹس جمع کرا سکتے ہیں:",
  "legal.ip.counter.1": "آپ کا نام، پتہ، اور رابطہ معلومات۔",
