  "legal.ip.counter.3": "نیک نیتی کا وہ بیان کہ مواد غلطی سے یا غلط شناخت کی بنیاد پر ہٹایا گیا ہے۔",
  "legal.ip.counter.4": "متنازعہ مواد کے لیے Visionex کے اندرونی جائزہ کے عمل میں حصہ لینے پر آپ کی رضامندی۔",
  "legal.ip.repeatTitle": "بار بار خلاف ورزی کرنے والے صارفین",
  "legal.ip.repeatBody": "وہ صارفین جو بار بار ذہنی املاک کے حقوق کی خلاف ورزی کرتے ہیں، ان کے اکاؤنٹس معطل کیے جا سکتے ہیں یا مستقل طور پر ختم کیے جا سکتے ہیں۔ پلیٹ فارم کی سالمیت، بار بار خلاف ورزی کرنے والے صارفین کے جائزے، اور قانونی تعمیل کے لیے Visionex ایسے ثابت شدہ نوٹسز کا ریکارڈ محفوظ رکھ سکتا ہے۔",
  "legal.ip.badFaithLabel": "بد نیتی کی رپورٹس:",
  "legal.ip.badFaithBody": "بد نیتی میں خلاف ورزی کے نوٹس جمع کرانا شرائطِ استعمال (Terms of Use) کی خلاف ورزی ہے اور اس سے رپورٹ کرنے والے اکاؤنٹ کے خلاف نفاذی کارروائی ہو سکتی ہے۔",
