  "legal.enforce.title": "نفاذ اور اپیل پالیسی",
  "legal.enforce.principleTitle": "ہمارا نفاذی اصول",
  "legal.enforce.principleBody": "Visionex کا مقصد پلیٹ فارم کے قوانین کو منصفانہ، شفاف، اور مستقل انداز میں لاگو کرنا ہے۔ تادیبی کارروائیاں خلاف ورزی کی شدت، تکرار، سیاق و سباق، اور اس کے اثرات پر مبنی ہوتی ہیں۔ Visionex کا نفاذی عمل ایک اندرونی پلیٹ فارم عمل ہے اور Visionex کو عدالت، ریگولیٹر، سرکاری ادارہ، یا باضابطہ تنازعہ حل کرنے والا ادارہ نہیں بناتا۔",
