  "legal.enforce.imm.5": "پلیٹ فارم سسٹمز کی جان بوجھ کر، مخصوص ہدف کے ساتھ سکیورٹی خلاف ورزیاں (security breaches)۔",
  "legal.enforce.factorsTitle": "وہ عوامل جو نفاذ کی سطح کو متاثر کرتے ہیں",
  "legal.enforce.factor.1": "خلاف ورزی کی نوعیت — قانونی جرم، کمیونٹی کو نقصان، یا انتظامی اصول۔",
  "legal.enforce.factor.2": "تکرار — یہ ایک الگ واقعہ ہے یا کسی نمونے کا حصہ؟",
  "legal.enforce.factor.3": "اثر — کیا اس خلاف ورزی سے دوسرے صارفین یا پلیٹ فارم کو نقصان پہنچا؟",
  "legal.enforce.factor.4": "نیت — کیا خلاف ورزی جان بوجھ کر کی گئی تھی یا غلط فہمی کا نتیجہ تھی؟",
  "legal.enforce.notifTitle": "آپ کو کیسے اطلاع دی جاتی ہے",
  "legal.enforce.notifBody": "جب کوئی نفاذی کارروائی کی جاتی ہے تو آپ کو آپ کے رجسٹرڈ ای میل ایڈریس کے ذریعے مطلع کیا جاتا ہے اور جہاں اکاؤنٹ تک رسائی ممکن ہو وہاں پلیٹ فارم کے اندرونی نوٹیفکیشن کے ذریعے بھی۔ اس نوٹیفکیشن میں مخصوص خلاف ورزی، کی گئی کارروائی، اس کی مدت، اور اپیل کا آپ کا حق شامل ہوتا ہے۔",
  "legal.enforce.appealTitle": "اپیل کا عمل",
  "legal.enforce.appealIntro": "آپ زیادہ تر نفاذی کارروائیوں کے خلاف اپیل کر سکتے ہیں۔ اپیل کرنے کے لیے:",
  "legal.enforce.appealStep.1": "hello@visionex.app پر مضمون (Subject) میں 'Account Appeal' کے ساتھ ای میل کریں۔",
  "legal.enforce.appealStep.2": "اپنا صارف نام، کارروائی کی تاریخ، اور صورتحال کا اپنا بیان شامل کریں۔",
  "legal.enforce.appealStep.3": "کوئی بھی ثبوت یا سیاق و سباق فراہم کریں جو آپ کی اپیل کی حمایت کرے۔",
  "legal.enforce.timelineTitle": "اپیل کی مدت",
  "legal.enforce.appealTime.submit": "آپ کو نافذ کرنے کی کارروائی کے 14 دن کے اندر اپنی اپیل جمع کروانی ہوگی۔",
  "legal.enforce.appealTime.confirm": "ہم جہاں ممکن ہو آپ کی اپیل کے موصول ہونے کی 2 کاروباری دنوں کے اندر تصدیق کرنے کا ہدف رکھتے ہیں۔",
  "legal.enforce.appealTime.review": "ہم جہاں ممکن ہو آپ کی اپیل کا جائزہ لے کر 14 کاروباری دنوں کے اندر فیصلہ جاری کرنے کا ہدف رکھتے ہیں۔",
  "legal.enforce.timelineNote": "اعلیٰ حجم یا پیچیدہ جائزوں کے ادوار میں، جائزہ مدت بڑھ کر 30 کاروباری دن یا اس سے زیادہ ہو سکتی ہے۔ ہم جہاں ممکن ہو آپ کو بڑے تاخیر کے بارے میں مطلع کرنے کا ہدف رکھتے ہیں۔",
  "legal.enforce.nonAppealTitle": "وہ کارروائیاں جن کے خلاف اپیل نہیں ہو سکتی",
  "legal.enforce.nonAppeal.1": "اوپر درج فوری-بین کی خلاف ورزیوں کے نتیجے میں مستقل پابندیاں۔",
  "legal.enforce.nonAppeal.2": "وہ مواد ہٹانے کے فیصلے جن میں وہ مواد اپیل سے 30 دن سے زیادہ پہلے لائیو تھا۔",
  "legal.enforce.nonAppeal.3": "تصدیق شدہ پالیسی خلاف ورزیوں کے نتیجے میں VX Coins کی ضبطی۔",
  "legal.enforce.removalLabel": "مواد ہٹانا:",
  "legal.enforce.removalBody": "سنگین صورتوں میں خلاف ورزی والا مواد بغیر پیشگی نوٹس کے ہٹا دیا جاتا ہے۔ کم شدت کے معاملات میں، صارفین کو ہٹانے سے پہلے مواد درست کرنے کے لیے 24 گھنٹے دیے جا سکتے ہیں۔ مواد ہٹانا خود بخود اکاؤنٹ لیول کی کارروائی کا نتیجہ نہیں بنتا۔",
  "legal.enforce.contact": "اپیلوں اور نفاذ سے متعلق سوالات کے لیے رابطہ کریں",
