  "legal.privacy.collect.messaging.text": "جب آپ فیس بک میسنجر یا انسٹاگرام ڈائریکٹ پر Visionex کے کسی پیج یا اکاؤنٹ کو پیغام بھیجتے ہیں تو میٹا ہمیں آپ کی لکھی ہوئی تحریر، آپ کے لیے میٹا کا اپنا محدود شناخت کنندہ (پیج یا انسٹاگرام اکاؤنٹ سے منسلک ایک شناخت — آپ کا پروفائل، ای میل یا فون نمبر نہیں)، پیغام کا شناخت کنندہ اور بھیجے جانے کا وقت بھیجتا ہے۔ ہم یہ سب اس لیے محفوظ کرتے ہیں تاکہ آپ کا سوال پڑھ سکیں، گفتگو کی ترتیب برقرار رکھ سکیں، ایک ہی پیغام کا دو بار جواب دینے سے بچ سکیں، اور جب خودکار مدد کافی نہ ہو تو معاملہ کسی فرد کے سپرد کر سکیں۔ جواب تیار کرنے کے لیے آپ کے پیغام کی تحریر فریقِ ثالث مصنوعی ذہانت فراہم کنندگان کے ذریعے پروسیس کی جاتی ہے۔ ہمیں آپ کا فیس بک یا انسٹاگرام پاس ورڈ، آپ کے دوستوں یا فالوورز کی فہرست، یا آپ کے پروفائل کی تفصیلات کبھی موصول نہیں ہوتیں۔",
