  "legal.dataDeletion.step2": "بتائیں کہ ڈیٹا کس سروس سے متعلق ہے — مثلاً فیس بک میسنجر یا انسٹاگرام ڈائریکٹ پر Visionex کے پیج کو بھیجا گیا کوئی پیغام — اور آپ نے ہم سے تقریباً کب رابطہ کیا تھا، تاکہ ہم درست گفتگو تلاش کر سکیں۔ اگر آپ کا Visionex اکاؤنٹ ہے تو درخواست اسی اکاؤنٹ کے ای میل پتے سے بھیجیں۔",
